export function searchTokens(query: string): TokenDef[] {
    const q = query.toLowerCase();
    return Object.values(TOKEN_REGISTRY).filter(t => t.key.includes(q) || t.displayName.toLowerCase().includes(q));
}
export const CATEGORY_COLORS: Record<string, string> = {
    damage: '#d80006',
    debuff: '#d80006',
    buff: '#f3bd04',
    special: '#a16c40',
    coin: '#a16c40',
    count: '#a16c40',
};
export function getCategoryColor(token: TokenDef): string {
    if (token.category === 'sin')
        return token.color;
    return CATEGORY_COLORS[token.category] ?? token.color;
}
import type { CustomStatus } from '../types/customStatus';
import { CLASSIFICATION_COLORS } from '../types/customStatus';
export function customStatusToTokenDef(status: CustomStatus): TokenDef {
    return {
        key: `custom_${status.key}`,
        displayName: status.name,
        category: 'special',
        color: CLASSIFICATION_COLORS[status.classification] || '#a16c40',
        iconPath: status.icon_url || undefined,
    };
}
export function getTokenDef(key: string, customStatuses: CustomStatus[]): TokenDef | undefined {
    const builtIn = TOKEN_REGISTRY[key];
    if (builtIn)
        return builtIn;
    const match = customStatuses.find(s => `custom_${s.key}` === key);
    return match ? customStatusToTokenDef(match) : undefined;
}
export function searchTokensWithCustom(query: string, customStatuses: CustomStatus[]): TokenDef[] {
    const q = query.toLowerCase();
    const builtIn = Object.values(TOKEN_REGISTRY).filter(t => t.key.includes(q) || t.displayName.toLowerCase().includes(q));
    const custom = customStatuses
        .map(customStatusToTokenDef)
        .filter(t => t.key.includes(q) || t.displayName.toLowerCase().includes(q));
    return [...builtIn, ...custom];
}
